// On its own: it sets data-theme on <html> and remembers it.
<ThemeToggle />

// In <head>, so a saved dark theme is there before the first paint.
<script dangerouslySetInnerHTML={{ __html: themeScript() }} />

// Or keep the theme in your app.
<ThemeToggle theme={theme} onThemeChange={setTheme} />

const columns: TableColumn<Person>[] = [
  { key: 'name', header: 'Name', sortable: true },
  { key: 'tasks', header: 'Open tasks', sortable: true, align: 'end' },
]

<Table caption="Team" columns={columns} rows={people} getRowId={(p) => p.id}
  selectable selected={selected} onSelectedChange={setSelected} />

const [value, setValue] = useState(['deploys'])

<CheckboxGroup
  label="Email me about"
  description="Pick as many as you like."
  options={[
    { value: 'deploys', label: 'Deploys', description: 'When a build goes live or fails' },
    { value: 'reviews', label: 'Review requests', description: 'When someone asks you to review' },
    { value: 'billing', label: 'Billing', description: 'Invoices and failed payments' },
  ]}
  value={value}
  onValueChange={setValue}
/>

// Every duration token is its base times --hl-motion-scale, so this one control retimes the app.
<Retime />

// Or set it from your own settings screen
applyRetime('slower')

// once, at the root
<ToastProvider><App /></ToastProvider>

// anywhere below
const { toast, update } = useToast()
toast({ title: 'Draft saved' })
// buds out of the button when it is within 240px of the toast
toast({ title: 'Payment received', origin: event.currentTarget })
toast({ title: 'File deleted', action: { label: 'Undo', onClick: restore } })
const id = toast({ title: 'Uploading', variant: 'loading', duration: Infinity })
update(id, { title: 'Upload complete', variant: 'success', duration: 4000 })
